def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find uniform full-width rows and full-height columns that divide the grid.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            divider = grid[r][0]
            break

    row_ranges = []
    start = 0
    for r in range(h):
        if all(v == divider for v in grid[r]):
            if start < r:
                row_ranges.append((start, r))
            start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == divider for r in range(h)):
            if start < c:
                col_ranges.append((start, c))
            start = c + 1
    if start < w:
        col_ranges.append((start, w))

    background = next(
        v for row in grid for v in row
        if v != divider
    )
    target = max(
        (v for row in grid for v in row if v not in (divider, background)),
        key=lambda v: sum(cell == v for row in grid for cell in row),
        default=None
    )

    result = []
    for r0, r1 in row_ranges:
        outrow = []
        for c0, c1 in col_ranges:
            count = sum(grid[r][c] == target
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            outrow.append(1 if count >= 2 else background)
        result.append(outrow)
    return result
